-- 0074 適用後チェック（SELECT1文・読み取り専用）。PASS/FAIL/INFO、最終行が総合判定。
with r(ord, level, item, detail) as (values
 (1, case when not has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v2(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text)'), 'execute') and not has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[])'), 'execute') and not has_function_privilege('authenticated', to_regprocedure('public.set_stylist_career_phase(text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, '旧経路（v2・v1・立場だけの保存）は authenticated が実行できない', ''),
 (2, case when not has_function_privilege('anon', to_regprocedure('public.save_stylist_profile_v2(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text)'), 'execute') and not has_function_privilege('service_role', to_regprocedure('public.save_stylist_profile_v2(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text)'), 'execute') and not has_function_privilege('anon', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') and not has_function_privilege('service_role', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, 'anon・service_role は v2・v3 を実行できない', ''),
 (3, case when has_function_privilege('authenticated', to_regprocedure('public.save_stylist_profile_v3(text,text,public.age_band,public.gender_type,text,text,integer,text,text[],public.employment_type,public.job_change_intent,public.salary_band,jsonb,text,public.profile_visibility,boolean,text,text[],date,text,text,date,text,date,text)'), 'execute') then 'PASS' else 'FAIL' end, 'v3は authenticated が実行できる（アプリの保存経路）', ''),
 (4, case when exists (select 1 from pg_trigger t where t.tgname='trg_career_phase_required_on_insert' and t.tgrelid='public.stylist_profiles'::regclass and t.tgenabled='O' and t.tgdeferrable and t.tginitdeferred) then 'PASS' else 'FAIL' end, '新しいプロフィール行は、コミット時に立場が3択でなければ作れない（遅延制約トリガーが有効）', ''),
 (5, case when exists (select 1 from pg_trigger where tgname='trg_career_phase_valid' and tgrelid='public.stylist_profiles'::regclass and tgenabled='O') then 'PASS' else 'FAIL' end, '立場を変える更新は3択のみ許可するトリガー（0073）が有効のまま', ''),
 (6, case when not has_table_privilege('authenticated','public.stylist_profiles','update') and not has_table_privilege('authenticated','public.stylist_profiles','insert') then 'PASS' else 'FAIL' end, 'authenticated は表を直接書けない（保存は関数経由のみ）', ''),
 (7, case when to_regprocedure('public.set_stylist_value_priorities(text[])') is null or has_function_privilege('authenticated', to_regprocedure('public.set_stylist_value_priorities(text[])'), 'execute') then 'PASS' else 'FAIL' end, '0072（適用していれば）の専用関数は影響を受けない', ''),
 (8, 'INFO', '立場の内訳（未設定 / 美容学生 / 新卒 / 現役 / ブランクあり）。適用前と同じはず（0074はデータを変更しない）', (select count(*) filter (where career_phase is null)::text||' / '||count(*) filter (where career_phase='student')::text||' / '||count(*) filter (where career_phase='new_graduate')::text||' / '||count(*) filter (where career_phase='experienced')::text||' / '||count(*) filter (where career_phase='blank')::text from public.stylist_profiles))
)
select ord, level, item, detail from (select ord::text as ord, level, item, detail from r
union all
select '99', case when (select count(*) from r where level='FAIL')=0 then 'PASS' else 'FAIL' end, '総合判定（INFO '||(select count(*) from r where level='INFO')||'件は人が確認）', 'FAIL '||(select count(*) from r where level='FAIL')||'件'
) t order by ord::int;
